import json

tx_storage = []

def handle(method, path, body):
    if method == "POST" and path == "/transactions":
        data = json.loads(body.decode())
        tx_storage.append(data)
        return (201, {"message": "交易記錄已新增"})

    elif method == "GET" and path == "/transactions":
        return (200, tx_storage)

    elif method == "GET" and path == "/balance":
        balance = 0
        for tx in tx_storage:
            if tx["type"] == "income":
                balance += tx["amount"]
            else:
                balance -= tx["amount"]
        return (200, {"balance": balance})

    else:
        return (404, {"error": "找不到資源"})

