document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('transactionForm');
    const transactionList = document.getElementById('transactionList');
    const balanceAmount = document.getElementById('balanceAmount');

    // 載入交易記錄和餘額
    loadTransactions();
    loadBalance();

    // 處理表單提交
    form.addEventListener('submit', async (e) => {
        e.preventDefault();

        const description = document.getElementById('description').value;
        const amount = parseFloat(document.getElementById('amount').value);
        const type = document.getElementById('type').value;

        try {
            // 呼叫API新增交易
            await fetch('api/transactions', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ description, amount, type })
            });

            // 重新載入資料
            loadTransactions();
            loadBalance();

            // 清空表單
            form.reset();
        } catch (error) {
            console.error('新增交易失敗:', error);
            alert('新增交易失敗');
        }
    });

    // 載入交易記錄
    async function loadTransactions() {
        try {
            const response = await fetch('api/transactions');
            const transactions = await response.json();

            transactionList.innerHTML = '';

            if (transactions.length === 0) {
                transactionList.innerHTML = '<li>沒有交易記錄</li>';
                return;
            }

            transactions.forEach(transaction => {
                const li = document.createElement('li');
                li.textContent = `${transaction.description} - ${transaction.type === 'income' ? '+' : '-'}${transaction.amount}`;
                transactionList.appendChild(li);
            });
        } catch (error) {
            console.error('載入交易記錄失敗:', error);
            transactionList.innerHTML = '<li>載入交易記錄失敗</li>';
        }
    }

    // 載入餘額
    async function loadBalance() {
        try {
            const response = await fetch('api/balance');
            const data = await response.json();
            balanceAmount.textContent = data.balance.toFixed(2);
        } catch (error) {
            console.error('載入餘額失敗:', error);
            balanceAmount.textContent = '錯誤';
        }
    }
});

